struct SavedShareHandle::Impl {
 std::shared_ptr<const storage::ProfileLease> lease;std::filesystem::path profile;std::uint64_t session=0;std::thread::id worker;std::stop_token lifetime;bool revoked=false;
 SavedShareDescription description;std::optional<storage::TorrentIntakeMetadata> metadata;detail::SharePolicy policy;detail::Payload payload;detail::Cache cache;detail::Named lock;std::string row;
};
SavedShareHandle::SavedShareHandle(std::shared_ptr<Impl> value)noexcept:impl_(std::move(value)){}
SavedShareHandle::SavedShareHandle(SavedShareHandle&&)noexcept=default;SavedShareHandle& SavedShareHandle::operator=(SavedShareHandle&&)noexcept=default;SavedShareHandle::~SavedShareHandle()=default;
const SavedShareDescription& SavedShareHandle::description()const noexcept{return impl_->description;}
const storage::TorrentIntakeMetadata& SavedShareHandle::metadata()const noexcept{return *impl_->metadata;}
